package snapshot

import (
	"encoding/hex"
	"testing"
)

func FuzzVEVSRestoreDoesNotPanic(f *testing.F) {
	golden, err := hex.DecodeString("")
	if err != nil {
		f.Fatalf("decode VEVS seed: %v", err)
	}
	f.Add(golden)
	f.Add([]byte("VEVS\x00\x04"))
	f.Add([]byte("not a snapshot"))

	f.Fuzz(func(t *testing.T, data []byte) {
		_, _ = Unmarshal(data)
	})
}
